import re, collections

def extract_grid(text, label):
    m=re.search(re.escape(label)+r'\n((?:[0-9]+(?: [0-9]+)*\n)+)',text)
    if not m: raise ValueError(label)
    return [[int(x) for x in line.split()] for line in m.group(1).strip().splitlines()]
