def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=collections.Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    # Count connected components for each non-background color, and detect the repeated isolated marker color.
    pos_by_color=collections.defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=bg: pos_by_color[v].append((r,c))
    isolated=[]
    for color,coords in pos_by_color.items():
        if len(coords)<2: continue
        coordset=set(coords); seen=set(); sizes=[]
        for p in coords:
            if p in seen: continue
            stack=[p];seen.add(p);size=0
            while stack:
                r,c=stack.pop();size+=1
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in coordset and q not in seen: seen.add(q);stack.append(q)
            sizes.append(size)
        if all(s==1 for s in sizes): isolated.append((len(coords),color))
    marker=max(isolated)[1]
    markers=pos_by_color[marker]
    pattern=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (bg,marker)]
    minr=min(r for r,c,v in pattern); maxr=max(r for r,c,v in pattern)
    minc=min(c for r,c,v in pattern); maxc=max(c for r,c,v in pattern)
    stamp=[[grid[r][c] for c in range(minc,maxc+1)] for r in range(minr,maxr+1)]
    out=[row[:] for row in grid]
    anchor_r=len(stamp)//2; anchor_c=len(stamp[0])//2
    for mr,mc in markers:
        tr=mr-anchor_r; tc=mc-anchor_c
        for i,row in enumerate(stamp):
            for j,v in enumerate(row):
                if 0<=tr+i<h and 0<=tc+j<w:
                    out[tr+i][tc+j]=v
    return out

